INSERT INTO `snnj_aysquiz_questions` (`id`, `author_id`, `category_id`, `question`, `question_title`, `question_image`, `wrong_answer_text`, `right_answer_text`, `question_hint`, `explanation`, `type`, `published`, `create_date`, `not_influence_to_score`, `weight`, `options`, `user_explanation`) VALUES (18927, 5, 5, 'If traffic is congested at an intersection, what is the appropriate course of action before entering it? Select the option that includes every correct item.', 'SKK51037', NULL, NULL, NULL, NULL, 'Correct answer: Both A and B. The passage below provides the relevant rule or safety guidance from this document.
